begin;
set local request.jwt.claims='{"aal":"aal2"}';
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000002101','push-staff@example.test'),('00000000-0000-4000-8000-000000002102','push-brand@example.test');
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000002101';
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000002101';
select lives_ok($$select public.subscribe_push('https://fcm.googleapis.com/fcm/send/unit-a','BA'||repeat('A',85),repeat('A',22))$$,'explicit own subscription accepted');
select lives_ok($$select public.subscribe_push('https://fcm.googleapis.com/fcm/send/unit-a','BA'||repeat('A',85),repeat('A',22))$$,'repeat subscription preserves one device');
select is((select count(id) from public.push_subscriptions),1::bigint,'only one subscription exists');
select is(public.claim_push_test('https://fcm.googleapis.com/fcm/send/unit-a','BA'||repeat('A',85),repeat('A',22)),true,'explicit test claims own matching encryption material');
select is(public.claim_push_test('https://fcm.googleapis.com/fcm/send/unit-a','BA'||repeat('A',85),repeat('A',22)),false,'test notification cooldown blocks repeated clicks');
select throws_ok($$select endpoint from public.push_subscriptions$$,'42501',null,'endpoint credentials are not directly readable');
select throws_ok($$select p256dh,auth from public.push_subscriptions$$,'42501',null,'keys are not directly readable');
select throws_ok($$select public.subscribe_push('https://localhost/private','BA'||repeat('A',85),repeat('A',22))$$,'23514',null,'arbitrary SSRF endpoint rejected in SQL');
select throws_ok($$select public.subscribe_push('https://fcm.googleapis.com.evil.test/send/a','BA'||repeat('A',85),repeat('A',22))$$,'23514',null,'push service suffix spoof rejected');
select throws_ok($$select public.subscribe_push('https://fcm.googleapis.com/fcm/send/b','CA'||repeat('A',85),repeat('A',22))$$,'23514',null,'invalid public key rejected');
select throws_ok($$select public.claim_push_reminders(now(),now()+interval '1 day')$$,'42501',null,'client cannot claim jobs');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000002102';
select is((select count(id) from public.push_subscriptions),0::bigint,'foreign subscription hidden');
select is(public.has_push_subscription('https://fcm.googleapis.com/fcm/send/unit-a'),false,'foreign endpoint lookup reveals no subscription');
select throws_ok($$select public.claim_push_test('https://fcm.googleapis.com/fcm/send/unit-a','BA'||repeat('A',85),repeat('A',22))$$,'42501',null,'brand cannot send test notification for an internal device');
select throws_ok($$select public.subscribe_push('https://fcm.googleapis.com/fcm/send/unit-a','BA'||repeat('A',85),repeat('A',22))$$,'42501',null,'a second account cannot take device consent');
select lives_ok($$select public.revoke_push_subscription('https://fcm.googleapis.com/fcm/send/unit-a')$$,'foreign revocation changes nothing');
reset role;
select is((select count(*) from public.push_subscriptions where user_id='00000000-0000-4000-8000-000000002101'),1::bigint,'foreign revocation preserves owner');
select ok(not exists(select 1 from public.audit_log where table_name='push_subscriptions' and (before ? 'endpoint' or after ? 'endpoint' or before ? 'auth' or after ? 'auth' or before ? 'p256dh' or after ? 'p256dh')),'audit contains no endpoint or encryption key');
insert into public.events(id,title,type,starts_at,ends_at,assigned_to) values('00000000-0000-4000-8000-000000002103','Private appointment','appointment','2038-01-02T10:00Z','2038-01-02T11:00Z','00000000-0000-4000-8000-000000002101');
create temporary table push_claim as select * from public.claim_push_reminders('2038-01-02T00:00Z','2038-01-03T00:00Z');
select is((select count(*) from push_claim),1::bigint,'active assigned appointment claimed');
select is((select count(*) from public.claim_push_reminders('2038-01-02T00:00Z','2038-01-03T00:00Z')),0::bigint,'concurrent scheduler cannot claim live lease');
select is(public.finish_push_reminder((select delivery_id from push_claim),gen_random_uuid(),'sent'),false,'wrong lease cannot complete');
select is(public.finish_push_reminder((select delivery_id from push_claim),(select lease_id from push_claim),'failed'),true,'failure recorded');
select is((select count(*) from public.claim_push_reminders('2038-01-02T00:00Z','2038-01-03T00:00Z')),0::bigint,'failure uses backoff');
update public.push_deliveries set attempted_at=now()-interval '16 minutes' where id=(select delivery_id from push_claim);
create temporary table push_retry as select * from public.claim_push_reminders('2038-01-02T00:00Z','2038-01-03T00:00Z');
select is((select count(*) from push_retry),1::bigint,'retry after backoff acquires a new lease');
select is(public.finish_push_reminder((select delivery_id from push_claim),(select lease_id from push_claim),'sent'),false,'stale original lease cannot complete retry');
select is(public.finish_push_reminder((select delivery_id from push_retry),(select lease_id from push_retry),'sent'),true,'current lease completes');
select is((select count(*) from public.claim_push_reminders('2038-01-02T00:00Z','2038-01-03T00:00Z')),0::bigint,'sent push never retried');
update public.events set starts_at='2038-01-02T12:00Z',ends_at='2038-01-02T13:00Z' where id='00000000-0000-4000-8000-000000002103';
create temporary table moved_claim as select * from public.claim_push_reminders('2038-01-02T00:00Z','2038-01-03T00:00Z');
select is((select count(*) from moved_claim),1::bigint,'rescheduled appointment receives a new reminder');
select is(public.finish_push_reminder((select delivery_id from moved_claim),(select lease_id from moved_claim),'discarded',true),true,'expired subscription is discarded atomically');
select is((select count(*) from public.push_subscriptions where user_id='00000000-0000-4000-8000-000000002101'),0::bigint,'expired device removed');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000002101';
select lives_ok($$select public.subscribe_push('https://fcm.googleapis.com/fcm/send/unit-new','BA'||repeat('A',85),repeat('A',22))$$,'new explicit consent after expiry');
select lives_ok($$select public.revoke_push_subscription()$$,'logout revokes every device consent');
select is((select count(id) from public.push_subscriptions),0::bigint,'revocation removes all own devices');
reset role;
select throws_ok($$select public.claim_push_reminders(now(),now()+interval '27 hours')$$,'22023',null,'oversized job period rejected');
select * from finish();rollback;
